package com.shiphappens.logistics.controller;
import com.shiphappens.logistics.entity.Statuses.UserRole; import com.shiphappens.logistics.service.AuthService; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/auth") public class AuthController { private final AuthService service; public AuthController(AuthService service){this.service=service;} public record LoginRequest(@Email @NotBlank String email,@NotBlank String password){} public record RegisterRequest(@Email @NotBlank String email,@Size(min=12,max=128) String password,@NotNull UserRole role){} @PostMapping("/login") public AuthService.LoginResult login(@RequestBody @jakarta.validation.Valid LoginRequest request){return service.login(request.email(),request.password());} @PostMapping("/register") public ResponseEntity<AuthService.LoginResult> register(@RequestBody @jakarta.validation.Valid RegisterRequest request){var user=service.register(request.email(),request.password(),request.role());return ResponseEntity.status(HttpStatus.CREATED).body(service.login(user.getEmail(),request.password()));} }
